import React from 'react';

import { getQuestionsWithMyAnswer } from '@apps/Interview/@services/interview.service';
import { IQuestionWithAnswer } from '@apps/Interview/@types/interview.types';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';

import QuestionForAnswer from '../QuestionForAnswer';

interface IInterviewResultProps {
  id_interview: number;
}

const InterviewResult: React.FC<IInterviewResultProps> = ({ id_interview }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  const [results, setResults] = React.useState<IQuestionWithAnswer[]>([]);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);

      const res = await getQuestionsWithMyAnswer(id_interview);
      setResults(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_interview]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div>
      {results[0]?.answer_date && (
        <PohAlert variant={AlertVariant.Success}>
          Завершено: {results[0].answer_date.toLocaleString()}{' '}
          {results[0].user.name + ' ' + results[0].user.surname}
        </PohAlert>
      )}
      {results.map((q) => {
        return <QuestionForAnswer key={q.id} item={q} result={q} disabled />;
      })}
    </div>
  );
};

export default InterviewResult;
